const projected=new T.Vector3(),tags=document.getElementById('object-tags');function labels(){if(!state||state.act>=5||window.forceFlat){tags.innerHTML='';return}let selected=[0,4].includes(state.act)?window.DuolaDemo.DATA.map(d=>d.id):[window.DuolaDemo.DATA[state.item].id];tags.innerHTML=selected.map(id=>{let g=objects[id];g.getWorldPosition(projected);projected.y+=id==='flower'?0:1;projected.project(camera);let x=(projected.x*.5+.5)*host.clientWidth,y=(-projected.y*.5+.5)*host.clientHeight;if(x<20||x>host.clientWidth*.74||y<20||y>host.clientHeight-70)return '';let d=window.DuolaDemo.DATA.find(d=>d.id===id),found=state.got.some(g=>g.id===id);return `<button class="object-tag ${found?'found':''}" data-id="${id}" style="left:${x}px;top:${y}px">${found?'✦':'＋'} ${d.cn}</button>`}).join('');tags.querySelectorAll('button').forEach(b=>b.onclick=()=>{window.DuolaDemo.selectItem(window.DuolaDemo.DATA.findIndex(d=>d.id===b.dataset.id))})}let last=0,frame=0;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;function animate(t){requestAnimationFrame(animate);if(t-last<32||document.hidden)return;const dt=previousTime===null?0:Math.min((t-previousTime)/1000,.1);previousTime=t;last=t;if(canOrbit()){yaw=T.MathUtils.lerp(yaw,targetYaw,.12);world.rotation.y=yaw;goal.set(13*zoom,(12+tilt)*zoom,18*zoom)}camera.position.lerp(goal,reduced?1:.045);look.lerp(goalLook,reduced?1:.045);camera.lookAt(look);if(!reduced){motionTime+=dt;if(state?.act<=4)walkAnimals(motionTime);train.position.x=Math.sin(t*Math.PI/40000)*5;particles.forEach((p,i)=>p.position.y=((i*.13-t*.0002)%3+3)%3);for(let id in starMap)starMap[id].rotation.y=t*.0005}r.render(scene,camera);if(frame++%8===0)labels()}requestAnimationFrame(animate);
